"use strict";
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const K={a:'#2453c9',b:'#d9480f',r:'#2b8a3e',d:'#7048e8',w:'#c92a2a',f:'#e67700',ink:'#1c2230',mut:'#5d6577',ax:'#9aa1b0',gr:'#eeeae0',line:'#e3ddcf',soft:'#e6ecfb'};
